<?php require __DIR__.'/../config.php';require __DIR__.'/../functions.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('bookings.php');verifyCsrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(!in_array($status,['confirmed','cancelled','completed'],true)){$status='confirmed';}try{db()->prepare('UPDATE bookings SET status=? WHERE id=?')->execute([$status,$id]);flash('success','Booking status updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('bookings.php');